inputs.requestsPostBodySchema:
{
    "userName": {
        "type": "string",
        "required": true,
        "description": "The new user's login / email address, used as the SCIM userName (e.g. jane.doe@example.com)."
    },
    "displayName": {
        "type": "string",
        "required": true,
        "description": "The user's full display name, e.g. 'Jane Doe'."
    },
    "name": {
        "type": "object",
        "required": true,
        "description": "Object with the given and family name, exactly: {\"givenName\": \"Jane\", \"familyName\": \"Doe\"}."
    },
    "emails": {
        "type": "array",
        "required": true,
        "description": "Array with the primary email, exactly: [{\"value\": \"jane.doe@example.com\", \"primary\": true}]."
    }
}

